// ArduCopter parameter metadata: a static asset generated by
// scripts/sync-params-meta.py from ArduPilot's own param_parse output, loaded on first use.

export interface ParamMeta {
  /** DisplayName */
  readonly n: string
  /** Description */
  readonly d: string
  /** Units */
  readonly u?: string
  /** Range [low, high] */
  readonly r?: readonly [number, number]
  /** Enumerated values {value: label} */
  readonly v?: Readonly<Record<string, string>>
  /** Bitmask {bit: label} */
  readonly b?: Readonly<Record<string, string>>
  /** Increment */
  readonly i?: number
  /** RebootRequired */
  readonly reboot?: boolean
}

export type MetaMap = Readonly<Record<string, ParamMeta>>

export const META_URL = '/params/arducopter.json'

let cached: Promise<MetaMap> | null = null

/** Fetches the metadata once per page; a failure resolves to an empty map (names still work). */
export function loadMeta(): Promise<MetaMap> {
  if (cached === null) {
    cached = fetch(META_URL, { credentials: 'same-origin' })
      .then((res) => (res.ok ? (res.json() as Promise<MetaMap>) : {}))
      .catch((error: unknown) => {
        console.error('parameter metadata failed to load:', error)
        return {}
      })
  }
  return cached
}

/** Test hook: forget the cached asset. */
export function resetMeta(): void {
  cached = null
}
